  "misconception": {
    "pack_id": null,
    "wrong": "Одиночный замер решает всё: если сигнала о коллекторе нет, коллектора нет.",
    "right": "Если отдельные замеры не выделяют коллектор, зону проникновения наблюдают во времени: повторными замерами или при смене условий.",
    "claims": ["c1", "c2", "c4"]
  },
  "data_meaning": {
    "inputs": [
      {"text": "Серия замеров одним методом в одной скважине при неизменных условиях: БЭЗ или комплекс фокусированных зондов.", "claims": ["c7", "c3"], "hypothesis": false},
      {"text": "Замеры до и после смены скважинных условий в методе двух растворов.", "claims": ["c4"], "hypothesis": false},
      {"text": "Нейтронные замеры в обсаженной скважине во время расформирования зоны.", "claims": ["c5"], "hypothesis": false}
    ],
    "outputs": [
      {"text": "Изменение показаний во времени, по которому судят о формировании или расформировании зоны.", "claims": ["c2"], "hypothesis": false},
      {"text": "Вывод о наличии газового коллектора при расформировании зоны.", "claims": ["c5"], "hypothesis": false}
    ],
    "breaks": [
      {"text": "Если условия в скважине меняются во время серии повторных замеров, изменение может быть вызвано не зоной.", "claims": ["c3"], "hypothesis": true},
      {"text": "Книга не даёт критерия, по которому изменение показаний считают признаком коллектора.", "claims": [], "hypothesis": false}
    ]
  },
  "it_analogy": {
    "pack_id": "IT05",
    "analogy": "Зона проникновения похожа на кэш, который перезаписывается рядом с точкой чтения. Повторные опросы показывают, как старые значения уходят.",
    "breaks_where": "Кэш сам расформировывается по своим правилам. Глубина зоны зависит от раствора и пористости. Аналогия не объясняет газ и не даёт порога.",
    "hypothesis": true
  },
  "now_nuance": {
    "text": "Сегодня повторные замеры чаще делают многозондовыми индукционными или боковыми приборами за один спуск, а данные обрабатывают программно. Газ ищут по расхождению нейтронной и плотностной пористости. Детали зависят от района.",
    "hypothesis": true
  },
  "threshold": {
    "is_threshold": true,
    "why": "Без идеи, что коллектор виден в изменении зоны во времени, не понять, зачем нужны повторные замеры и метод двух растворов."
  },
  "inefficiency": {
    "inputs": [
      "Результаты отдельных замеров, которые не позволили выделить коллектор.",
      "Данные каротажа одним методом: БЭЗ или комплекс фокусированных зондов."
    ],
    "manual_steps": [
      "Повторно проводить замеры тем же методом в тех же условиях.",
      "При смене скважинных условий проводить новый замер по методу двух растворов.",
      "В обсаженной скважине повторять нейтронные замеры во время расформирования зоны."
    ],
    "judgment_points": [
      "Решить, что отдельных замеров недостаточно.",
      "Выбрать между повторными замерами и методом двух растворов по состоянию скважины.",
      "Понять, идёт ли формирование или расформирование зоны."
    ],
    "time": [
      "Наблюдение «во времени» занимает всю серию повторных замеров. Книга не называет срок."
    ],
    "typical_errors": [
      "Сделать повторный замер при изменившихся условиях и принять разницу за коллектор (вывод из условия c3, не прямая цитата).",
      "Считать динамические методы заменой всем замерам, хотя книга применяет их, когда отдельные не решают задачу."
    ]
  },
